import{_ as a,c as t,o as i,ag as r}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"P01 — Account setup","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/practitioner-01.md","filePath":"practice/aws/practitioner-01.md"}'),s={name:"practice/aws/practitioner-01.md"};function o(n,e,l,c,d,u){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="p01-—-account-setup" tabindex="-1">P01 — Account setup <a class="header-anchor" href="#p01-—-account-setup" aria-label="Permalink to “P01 — Account setup”">​</a></h1><p><strong>Learner status: not started. All supplied tasks on this page are mandatory in this learning path</strong>, including items originally labelled optional or bonus. Repeating tasks still require the stated action or comparison; reuse earlier resources and code where suitable, and record the new evidence. Source optional labels describe the original course only.</p><p><strong>Read first:</strong> <a href="./../../aws/account-and-tools.html">account and tools</a>. <strong>Overlap:</strong> Recheck account/MFA/CLI/billing in A01; no second account is needed.</p><h2 id="task-1-1-—-set-up-your-aws-account" tabindex="-1">Task 1.1 — Set up your AWS account <a class="header-anchor" href="#task-1-1-—-set-up-your-aws-account" aria-label="Permalink to “Task 1.1 — Set up your AWS account”">​</a></h2><ul><li>[ ] Create and verify an AWS account. Protect the root user and enable MFA.</li><li>[ ] Create an everyday-work IAM user with <code>AdministratorAccess</code> and MFA, as required by this course exercise. See <a href="./source-notes.html">the distinction from the recommended temporary-credential setup</a>.</li><li>[ ] Install and configure AWS CLI with the exercise user&#39;s credentials and a deliberate Region. Confirm account access, for example:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get-user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user-name=MyUser</span></span></code></pre></div><ul><li>[ ] Enable applicable Free Tier usage notifications and configure AWS Budget alerts. Record recipients and thresholds without publishing private details. Alerts do not impose a universal hard spending cap.</li></ul><h2 id="task-1-2-—-understand-the-template-repository" tabindex="-1">Task 1.2 — Understand the template repository <a class="header-anchor" href="#task-1-2-—-understand-the-template-repository" aria-label="Permalink to “Task 1.2 — Understand the template repository”">​</a></h2><ul><li>[ ] Read the course <a href="https://autocode.git.epam.com/ld-autocode-js-programs/cloudx-aws-practitioner-for-js/cloudx-aws-practitioner-for-js-template" target="_blank" rel="noreferrer">template repository</a> README and its setup/submission workflow.</li><li>[ ] Let Autocode create the learner fork when starting Module 2; do not manually fork or clone the template ahead of that workflow. Read “check out the template” as reviewing it at this stage.</li></ul><h2 id="evaluation-criteria" tabindex="-1">Evaluation criteria <a class="header-anchor" href="#evaluation-criteria" aria-label="Permalink to “Evaluation criteria”">​</a></h2><p>Account created and verified; root MFA enabled; exercise administrator IAM user created with MFA; CLI installed and authenticated; applicable Free Tier notifications enabled; Budget alerts configured. Record actual results, not just a configuration intention.</p><h2 id="completion-evidence" tabindex="-1">Completion evidence <a class="header-anchor" href="#completion-evidence" aria-label="Permalink to “Completion evidence”">​</a></h2><p>Record each required task, the observed acceptance results, applicable test output, all promoted extensions, and cleanup. Original Autocode checks do not automatically verify the promoted extensions. See the <a href="./#evidence-for-every-required-module">shared evidence rules</a>.</p>',13)])])}const m=a(s,[["render",o]]);export{h as __pageData,m as default};
